  ["Rings of your emotes, lines and macros on one key; a thank-you when someone buffs or resurrects you; a bow or a polite no to a duel or a trade."] = "Ringe deiner Emotes, Zeilen und Makros auf einer Taste; ein Dank, wenn dich jemand bufft oder wiederbelebt; eine Verbeugung oder ein höfliches Nein zu einem Duell oder Handel.", -- luacheck: ignore 631
  ["Roleplay with Bastian's"] = "Rollenspiel mit Bastian's",
  ["Route steps"] = "Routenschritte",
  ["Route there on anything: road, flight, boat."] = "Eine Route zu allem: Straße, Flug, Schiff.",
  ["Show the welcome at every login"] = "Das Willkommen bei jedem Login zeigen",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Gemeinsam am Feuer sitzen, es mit der Gruppe teilen, ein Lagerring für den Abend.", -- luacheck: ignore 631
  ["Switch on %s on the Suite page."] = "Schalte %s auf der Suite-Seite ein.",
  ["Talk to a quest giver with the conversation on"] = "Mit einem Questgeber sprechen, das Gespräch eingeschaltet", -- luacheck: ignore 631
  ["Talk to people without quest windows"] = "Mit Leuten reden ohne Questfenster",
  ["Text"] = "Text",
  ["The Gestures ring"] = "Der Gesten-Ring",
  ["The Orbiter"] = "Der Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "Der Orbiter spielt Spokens Stimmen für Quests, Orte, Bücher und Bosse und die Stimme des Spiels, wo Spoken keine hat.", -- luacheck: ignore 631
  ["The Orbiter plays the zone's story."] = "Der Orbiter spielt die Geschichte der Zone.",
  ["The campfire"] = "Das Lagerfeuer",
  ["The hub: every app's settings, the Suite page, Help."] = "Der Hub: die Einstellungen jeder App, die Suite-Seite, Hilfe.", -- luacheck: ignore 631
  ["The land speaks"] = "Das Land spricht",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "Das Land erzählt seine Geschichten, während du gehst (der Orbiter mit Spoken)", -- luacheck: ignore 631
  ["The screen for the view"] = "Der Bildschirm für die Aussicht",
  ["The search opens a page for anything."] = "Die Suche öffnet eine Seite für alles.",
  ["The suite's button at the minimap"] = "Der Knopf der Suite an der Minikarte",
  ["The suite's words"] = "Die Worte der Suite",
  ["The way there, by road, flight and boat"] = "Der Weg dorthin, über Straße, Flug und Schiff",
  ["The welcome stays away at login; the General page brings it back."] = "Das Willkommen bleibt beim Login weg; die Allgemein-Seite holt es zurück.", -- luacheck: ignore 631
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "Das Willkommensfenster bei jedem Login, bis Nicht mehr zeigen in seiner Ecke (plan-launch-version D).", -- luacheck: ignore 631
  ["Try it"] = "Ausprobieren",
  ["What matters for this way"] = "Was für diesen Weg zählt",
  ["What you get"] = "Was du bekommst",
  ["Where things are"] = "Wo die Dinge sind",
  ["You know the way."] = "Du kennst den Weg.",
  ["Your first five minutes"] = "Deine ersten fünf Minuten",
  ["Your gestures on a ring, thanks in your own words"] = "Deine Gesten auf einem Ring, Dank in deinen eigenen Worten", -- luacheck: ignore 631
  ["Your pack"] = "Dein Gepäck",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Hochgipfel",
  ["Greenback Ridge"] = "Grünrücken",
  ["Peacebloom"] = "Friedensblume",
  ["%d yd high, %d yd away"] = "%d Meter hoch, %d Meter entfernt",
  ["%d yd away"] = "%d Meter entfernt",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Karte von %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Karte von %s (%s), mit freundlicher Genehmigung. Danke!",
  ["Click, then Ctrl+C to copy the address"] = "Klicken, dann mit Strg+C die Adresse kopieren",
  -- the minimap buttons
  ["Welcome"] = "Willkommen",
  ["Its own minimap button for the welcome"] = "Eigener Minimap-Button für die Begrüßung",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Ein Button an der Minimap, der die Begrüßung mit dem Wanderer und dem Gelehrten wieder zeigt.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s ist ausgeschaltet. Auf seiner Seite schaltest du es ein.",
  ["Click: its page, to switch it on."] = "Klick: seine Seite, zum Einschalten.",

  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "Bastians Minikarte zeigt die Kräuter, Erze und Kreaturen, die dein Aufspüren findet, nun auch in ihren eigenen Stilen, und der Aufspüren-Knopf des Spiels ist zurück in ihrer Werkzeugleiste.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "Der Sitzungsplan (was in die nächsten 30 bis 180 Minuten passt) ist von Routes Erkunden zu Bastian's Gold gewandert und bleibt aus, bis du ihn in Golds Einstellungen einschaltest.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "Andere Addons können Bastian's über Bastians.API nach Namen und Orten jeder Sache, deinen Notizen in der Nähe eines Punkts und deinem Goldeinkommen fragen.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Wenn Bastian's Helpers einen Gegenstand nachkauft, sagt es dir, ob ein anderer Händler ihn billiger verkauft und wo.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "Was ist neu spricht deine Sprache: Deutsch, Französisch, Spanisch, Koreanisch und Chinesisch.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "Die Preisseite eines Gegenstands zeigt eine kleine Kurve der Preise, die deine eigenen Auktionshaus-Scans in den letzten zwei Wochen gesehen haben.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Postregeln: sag Helpers, welcher Charakter deine Kräuter, Erze, Stoffe und mehr bekommt; ein Klick neben dem Senden-Reiter füllt die Post.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "Campfire kann dein Feuer in einem öffentlichen Kanal teilen und die Feuer aller zeigen (standardmäßig aus, mit einer Sperrliste).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "Bastian's Suite spricht jetzt Russisch und brasilianisches Portugiesisch.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Ein Gestures-Befehl kann jetzt zaubern, benutzen und anvisieren: /cast und Co. laufen als Makro, wenn du den Keil anklickst.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "Andere Addons können über Bastians.API jetzt Bastian's Wegpunkt lesen und setzen sowie das Gold des Accounts und die Gegenstandsgruppen der Suite lesen.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "Spoken 3.8.0, die Version des Launch-Clients, gilt jetzt als getestet; der Hub meldet sie nicht mehr als neuer.",
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "Die Stimme des Spiels, die Questtexte vorliest, ist standardmäßig eine Frauenstimme und lässt sich in den Einstellungen des Orbiters wählen.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Ohne Spoken liest der Orbiter den Text einer Quest mit der Stimme des Spiels vor (Einstellungen für Barrierefreiheit).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (das umbenannte Voice-Addon): Das Panel behält seinen Platz und wächst um seine Mitte, sagt, was es abspielt und was ein Klick bewirkt hat, hat Piktogramm-Bedienelemente und einen eigenen Minimap-Button; die Einstellungsseiten der Suite im Spiel lassen sich scrollen.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice: Abspielen bei Quests, Zonen, Gebieten, Bossen und Büchern, wo Spoken eine Zeile hat, der Geschichtenkreis um dich herum und Questgespräche ohne die Fenster des Spiels (standardmäßig aus).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Eine Notiz, die du auf der Seite eines Dungeons (oder einer anderen Seite) hinzufügst, erscheint jetzt auf dieser Seite.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "Die Suche der Minimap findet nur NPCs, Quests, Zonen, deine Notizen und Lesezeichen und markiert den Ort, zu dem sie springt; eine Quest markiert ihren Questgeber.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Auf der Karte zeigen" zeichnet jetzt, was du gewählt hast (sein Symbol und seinen Namen an jedem Ort), und wählt es aus, auch wenn seine Ebene ausgeschaltet ist.',
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = 'Die Karte hat eine Ebene "Dungeons und Raids", die sich von selbst einschaltet, wenn du im Browser einen Dungeon wählst.',
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Neue App Bastian's Helpers: verkauft Plunder, repariert, kauft Vorräte nach, nimmt alle Post, hilft bei Questgebern und zeigt IDs in Tooltips.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "Die Dungeon-Seiten nennen die richtigen Bosse; einige zeigten eine fremde Kreatur (der erste Boss der Burg Schattenfang als Archaedas) mit Beute, die nicht seine eigene war.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Minimap-Buttons schließen, was sie geöffnet haben; der Button der Gesten öffnet deren Optionen; der Button einer ausgeschalteten App führt zu ihrem Schalter; ein neuer Button zeigt die Begrüßung erneut.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "Forevers eigene Dungeons (Dalaran, die Ausgrabung in den Sumpflanden, die Halle der Thane, die Ruinen von Lordaeron) zeigen jetzt die handgezeichneten Karten von Santiago Reyes mit markierten Bossen - danke, Santiago!",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Deutsche, französische und spanische Spieler lesen die vollständigen Texte der meisten Quests in ihrer Sprache, und die AddOn-Liste spricht jede Sprache der Suite.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'Die AddOn-Liste des Spiels zeigt die Suite als eine einklappbare Kopfzeile "Bastian\'s Suite", mit den Datenpaketen und Kartenstilen unter ihrer App eingeklappt, auch auf Koreanisch und Chinesisch.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Koreanische und chinesische Spieler lesen die vollständigen Questtexte in ihrer Sprache, und Bastian's Chat spricht Französisch, Spanisch, Koreanisch und Chinesisch.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Mit Total RP 3 oder MyRolePlay zeigen Chat, Gestures und der Orbiter die Rollenspielnamen anderer Spieler an.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Ein neuer Willkommensbildschirm: Wähle den Wanderer oder den Gelehrten mit einem Bild deines eigenen Volkes, richte dein Paket ein und probiere deine ersten fünf Minuten Schritt für Schritt aus.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire: eine Karte, solange ein Feuer in der Nähe ist, ein Lagerring in den Gesten, das Feuer mit Gruppe und Gilde teilen und eine Übersicht aller Lagerfunktionen.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Emotes in Bastian's Chat erscheinen jetzt in der eigenen Emote-Farbe des Farbschemas, fürs Rollenspiel.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = 'Ein Gesten-Keil kann per Klick eines deiner eigenen Makros ausführen und führt die Befehle des Spiels aus, etwa /reload; die Gegenstands-Buttons von Quests funktionieren mit "Bei Tastendruck zaubern".',
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Die koreanischen und chinesischen Texte der Suite lesen sich natürlich und verwenden die Begriffe des Spiels.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Baue deine Gesten-Ringe nach Belieben: benenne sie, wähle beliebige Emotes, eigene Zeilen, Befehle sowie die Bedienelemente der Suite und des Spiels über einen einzigen Filter; das Rad dreht sich in die richtige Richtung; die Auswahlmöglichkeiten eines Gesprächs überlappen sich am Orbiter nicht mehr.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Wenn dich jemand herausfordert, mit dir handelt oder dich einlädt, bieten die Gesten eine Verbeugung, ein Winken oder eine höfliche Absage an; das +-Menü des Chats hat einen Rollenspiel-Tab.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = 'Die Keile "Route nach Hause", "Als gehört markieren" und "Tracker ein/aus" der Gesten leuchten jetzt auf.',
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "Der Orbiter meldet, wenn dein Spoken neuer oder älter ist als die Version, mit der die Suite getestet wurde, redet nie über Spoken oder Spoken Players hinweg, und Bastian's Helpers, Chat und der Orbiter erscheinen auf Broker-Anzeigen; andere Addons können fragen, wer ein Rezept kennt, den Orbiter sprechen lassen, dein Spielprofil lesen und jede App öffnen.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Jede App trägt ihr eigenes Zeichen an der Minimap, im Hub, auf Broker-Anzeigen und in der AddOn-Liste: ein Kompassstern für die Suite, eine Schriftrolle für Quests, eine Markierung für die Karte, eine Lupe für den Browser, eine Waage für Gold, ein Wegweiser für Route, eine Feder für Notizen, zwei Figuren für Alts, ein Schraubenschlüssel für Helpers, Sprechblasen für Chat, eine Hand für Gestures.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Wähle beim ersten Start, wie du spielst: Der Wanderer hört Azeroth fast ohne Oberfläche, der Gelehrte hat jede Quest, Kreatur, jeden Gegenstand und Ort einen Klick entfernt; Bastian's Gestures bringt Emote-Ringe und Höflichkeit; der Hub erklärt jede App und jede Taste.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Jeder Button zeigt wieder sein Piktogramm und die Wörter sitzen, wo sie hingehören; Chat-Tabs und Buttons lassen sich leicht unterscheiden; die Bedienelemente des Orbiters klicken, solange eine Kreatur zu sehen ist, sein Hub zieht ihn, und seine Antworten sind Symbole; auf der Seite eines Gegenstands steht, welcher deiner Charaktere ihn hat.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Lehrer sagen auf der Karte und auf ihrer Seite, was sie lehren, und ihre Zauberliste zeigt, wer von deinen Charakteren jeden einzelnen kennt; Gegenstandslisten lassen sich danach filtern, wem ein Gegenstand gehört; der Orbiter verschwindet mit der Taste zum Leeren des Bildschirms und lässt sich an seinem Hub ziehen; die Hover-Vorschau des Browsers ist eine Einstellung.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Jede App bietet einen Data-Broker-Feed (Titan, Bazooka, ElvUI und dergleichen), das Addon-Fach listet die Suite auf, Taschen-Addons bekommen die Gegenstandssets der Suite, und andere Addons können die Suite über Bastians.API lesen.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = 'Die Blasen des Orbiters gleiten an ihre Plätze, und die gerade abgespielte ist eingefärbt; "Auf der Karte zeigen" zeichnet immer, was du gewählt hast; der Plunderfilter säubert auch die Zeilen, die schon auf dem Bildschirm stehen; die Stimme des Spiels wird gefunden, sobald der Client sie auflistet.',
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Sieben Looks zur Auswahl, darunter Nacht, Glas und Pergament; jeder Button der Suite zeigt ein Piktogramm; jedes Farbschema ist auf lesbaren Text geprüft.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "Die Filter-Pillen des Browsers nutzen die Breite des Bereichs und die erste Zeile wird nie verdeckt, die Mobs-Suche funktioniert wieder, Zonen erscheinen nur einmal, eine Vorschau braucht Shift, und eine auf einer Seite gespeicherte Notiz erscheint sofort.",
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = 'Eine Suchsyntax in jedem Suchfeld (Wörter, "Phrasen", OR, -not, field:value, level>30), die Texttasten Ctrl+Backspace/Delete/Left/Right, eine Taste, die den Bildschirm für Rollenspiel leert, eine Sperre für jedes Fenster und die neue Look-Engine hinter Modern und WoW.',
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'Bastian\'s Helpers schreibt seine Meldungen auch in einen Chat-Tab namens "Addons", wenn du einen hast.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = "Der Farbwähler öffnet sich vor den Einstellungen, und im Kampf erscheint keine Meldung über Blockierung mehr.",
  ["The map's layer bar names each icon the moment you point at it."] = "Die Ebenenleiste der Karte nennt jedes Symbol, sobald du darauf zeigst.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "Andere Addons können Bastian's nach Preisen, Questständen, der aktiven Route und Reisezeiten fragen, eine Route starten und über Bastians.API auf ihre Ereignisse hören.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Breite Buttons im WoW-Look behalten die runden Enden des Spiels, statt sie zu dehnen.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Bastian's Apps erscheinen in Titan Panel, Bazooka, den Datenleisten von EllesmereUI und jeder anderen LibDataBroker-Anzeige sowie im Addon-Fach, und sortieren deine Taschen in BetterBags, Baganator und AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "Bastian's Chat bekommt einen Live-Filter für Tabs, Tab-Fenster, die wieder andocken, einen Messenger im Stil von WhatsApp mit Klassensymbolen und einer Suche sowie eine Sperre für jedes Chatfenster.",
})
